module adder_16bit (
    input wire [15:0] a,
    input wire [15:0] b,
    input wire Cin,
    output wire [15:0] y,
    output wire Co
);
    wire [15:0] sum;
    wire [15:0] carry;

    assign sum[0] = a[0] ^ b[0] ^ Cin;
    assign carry[0] = (a[0] & b[0]) | (Cin & (a[0] ^ b[0]));

    genvar i;
    generate
        for (i = 1; i < 16; i = i + 1) begin : adder_loop
            assign sum[i] = a[i] ^ b[i] ^ carry[i-1];
            assign carry[i] = (a[i] & b[i]) | (carry[i-1] & (a[i] ^ b[i]));
        end
    endgenerate

    assign y = sum;
    assign Co = carry[15];

endmodule

