module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output reg [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH:0] pipe_reg [0:STG_WIDTH-1];
reg [3:0] stage_counter;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        stage_counter <= 0;
        o_en <= 0;
        result <= 0;
    end else if (i_en) begin
        pipe_reg[0] <= {1'b0, adda} + {1'b0, addb};
        for (integer i = 1; i < STG_WIDTH; i = i + 1) begin
            pipe_reg[i] <= pipe_reg[i-1];
        end
        if (stage_counter < STG_WIDTH) begin
            stage_counter <= stage_counter + 1;
        end else begin
            result <= pipe_reg[STG_WIDTH-1];
            o_en <= 1;
            stage_counter <= 0;
        end
    end else begin
        o_en <= 0;
    end
end

endmodule

