reg [DATA_WIDTH-1:0] stage_b [0:STG_WIDTH-1];
reg [DATA_WIDTH-1:0] stage_result [0:STG_WIDTH-1];
integer i;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        o_en <= 0;
        result <= 0;
        for (i = 0; i < STG_WIDTH; i = i + 1) begin
            stage_a[i] <= 0;
            stage_b[i] <= 0;
            stage_result[i] <= 0;
        end
    end else if (i_en) begin
        stage_a[0] <= adda;
        stage_b[0] <= addb;
        for (i = 1; i < STG_WIDTH; i = i + 1) begin
            stage_a[i] <= stage_a[i-1];
            stage_b[i] <= stage_b[i-1];
            stage_result[i] <= stage_a[i] + stage_b[i];
        end
        result <= stage_result[STG_WIDTH-1];
        o_en <= 1;
    end else begin
        o_en <= 0;
    end
end

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output reg [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH-1:0] a_reg, b_reg;
reg [DATA_WIDTH:0] sum;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        a_reg <= 0;
        b_reg <= 0;
        sum <= 0;
        o_en <= 0;
    end else if (i_en) begin
        a_reg <= adda;
        b_reg <= addb;
        sum <= a_reg + b_reg;
        o_en <= 1;
    end else begin
        o_en <= 0;
    end
end

always @(posedge clk) begin
    if (o_en)
        result <= sum;
end

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output reg [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH-1:0] a_reg, b_reg;
reg [DATA_WIDTH:0] sum;
reg [3:0] state;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        a_reg <= 0;
        b_reg <= 0;
        sum <= 0;
        o_en <= 0;
        state <= 0;
    end else begin
        if (i_en) begin
            a_reg <= adda;
            b_reg <= addb;
            sum <= {1'b0, a_reg} + {1'b0, b_reg}; // Add with carry
            state <= 1;
        end

        if (state == 1) begin
            result <= sum;
            o_en <= 1;
            state <= 0;
        end else begin
            o_en <= 0;
        end
    end
end

endmodule

