module calendar(CLK,RST,Hours,Mins,Secs);
input CLK,RST;
output [5:0] Hours,Mins,Secs;
reg [5:0] Hours,Mins,Secs;

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        Hours <= 6'b0;
        Mins <= 6'b0;
        Secs <= 6'b0;
    end else begin
        Secs <= Secs + 1;
        if (Secs == 6'd60) begin
            Secs <= 6'b0;
            Mins <= Mins + 1;
            if (Mins == 6'd60) begin
                Mins <= 6'b0;
                Hours <= Hours + 1;
                if (Hours == 6'd24) begin
                    Hours <= 6'b0;
                end
            end
        end
    end
end
endmodule

