parameter IDLE = 2'b00, MATCHING = 2'b01, MATCHED = 2'b10;

always @(posedge CLK or posedge RST) begin
    if (RST) 
        state <= IDLE;
    else 
        state <= next_state;
end

always @(*) begin
    case(state)
        IDLE: begin
            MATCH = 0;
            if (IN) 
                next_state = MATCHING;
            else 
                next_state = IDLE;
        end
        MATCHING: begin
            MATCH = 0;
            if (IN) 
                next_state = MATCHED;
            else 
                next_state = IDLE;
        end
        MATCHED: begin
            MATCH = 1;
            if (~IN) 
                next_state = IDLE;
            else 
                next_state = MATCHED;
        end
        default: begin
            MATCH = 0;
            next_state = IDLE;
        end
    endcase
end

