                        product <= product + (a_reg << count);
                    end
                    b_reg <= b_reg >> 1;
                    count <= count + 1;
                end else begin
                    yout <= product;
                    done <= 1'b1;
                    state <= 1'b0; // Go back to idle state
                end
            end
        endcase
    end
