module multi_booth_8bit (p, rdy, clk, reset, a, b);
   input clk, reset;
   input [7:0] a, b;
   output reg [15:0] p;
   output reg rdy;

   reg [7:0] Q;
   reg [7:0] M;
   reg [15:0] A;
   reg [3:0] count;
   reg [1:0] Q_1;

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         p <= 0;
         rdy <= 0;
         A <= 0;
         Q <= 0;
         M <= 0;
         count <= 0;
         Q_1 <= 0;
      end else begin
         if (count == 0) begin
            M <= b;
            Q <= a;
            A <= 0;
            Q_1 <= 0;
            count <= 8;
            rdy <= 0;
         end else if (count > 0) begin
            case ({Q[0], Q_1})
               2'b01: A <= A + M; // A = A + M
               2'b10: A <= A - M; // A = A - M
               default: ;
            endcase
            {A, Q} <= {A, Q} >> 1; // Arithmetic right shift
            Q_1 <= Q[0];
            count <= count - 1;
         end else if (count == 0) begin
            p <= {A, Q}; // Final result
            rdy <= 1;    // Indicate ready
         end
      end
   end
endmodule

`timescale 1ns / 1ps
module multi_booth_8bit (p, rdy, clk, reset, a, b);
   input clk, reset;
   input [7:0] a, b;
   output reg [15:0] p;
   output reg rdy;

   reg [15:0] A, S, P;
   reg [3:0] count;
   reg [1:0] Q;
   reg [7:0] multiplicand;
   reg [7:0] multiplier;

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         p <= 16'b0;
         rdy <= 0;
         count <= 4'b0;
         Q <= 2'b0;
         A <= 16'b0;
         S <= 16'b0;
         P <= 16'b0;
         multiplicand <= a;
         multiplier <= b;
      end else begin
         case (count)
            4'b0000: begin
               A <= {8'b0, multiplicand};  // Load multiplicand
               S <= {8'b0, ~multiplicand + 1'b1};  // Load -multiplicand
               P <= {8'b0, multiplier};  // Load multiplier
               Q <= 2'b00;  // Initialize Q
               count <= count + 1;
            end
            4'b0001: begin
               if (P[1:0] == 2'b01) begin
                  P <= P + A;  // P = P + A
               end else if (P[1:0] == 2'b10) begin
                  P <= P + S;  // P = P + (-A)
               end
               P <= {P[15:1], Q[0]};  // Shift right
               Q <= {P[0], Q[1]};  // Update Q
               count <= count + 1;
            end
            default: begin
               if (count < 4'b1000) begin
                  if (P[1:0] == 2'b01) begin
                     P <= P + A;  // P = P + A
                  end else if (P[1:0] == 2'b10) begin
                     P <= P + S;  // P = P + (-A)
                  end
                  P <= {P[15:1], Q[0]};  // Shift right
                  Q <= {P[0], Q[1]};  // Update Q
                  count <= count + 1;
               end else begin
                  p <= P;  // Final product
                  rdy <= 1;  // Indicate ready
                  count <= count;  // Hold state
               end
            end
         endcase
      end
   end
endmodule

