module multi_booth_8bit (p, rdy, clk, reset, a, b);
   input clk, reset;
   input [7:0] a, b;
   output reg [15:0] p;
   output reg rdy;

   reg [15:0] A, Q, M, Q_1;
   reg [3:0] count;
   reg [1:0] state;

   parameter IDLE = 2'b00, LOAD = 2'b01, CALC = 2'b10, FINISH = 2'b11;

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         p <= 16'b0;
         rdy <= 1'b0;
         count <= 4'b0;
         state <= IDLE;
      end else begin
         case (state)
            IDLE: begin
               if (a != 8'b0 && b != 8'b0) begin
                  M <= {8'b0, b};
                  A <= 16'b0;
                  Q <= {8'b0, a};
                  Q_1 <= 1'b0;
                  count <= 8; 
                  state <= LOAD;
               end
            end

            LOAD: begin
               if (count > 0) begin
                  case ({Q[0], Q_1})
