                  Q <= {A[0], Q[15:1]};
                  A <= A >> 1;
                  count <= count - 1;
               end else begin
                  state <= FINISH;
               end
            end

            FINISH: begin
               p <= {A, Q[7:0]};
               rdy <= 1'b1;
               state <= IDLE;
            end
         endcase
      end
   end
