                     2'b10: product <= product - {8'b0, multiplicand};
                  endcase
                  product <= product >> 1;
                  multiplier <= {1'b0, multiplier[7:1]};
                  count <= count - 1;
               end else begin
                  state <= DONE;
               end
            end
            DONE: begin
               p <= product;
               rdy <= 1;
               state <= IDLE;
