                     end
                     2'b00, 2'b11: begin
                        Q <= {Q[15:1], Q_1}; 
                        Q_1 <= Q[0]; 
                     end
                  endcase
                  count <= count - 1;
               end else begin
                  p <= A + Q; 
                  rdy <= 1'b1; 
                  state <= DONE;
               end
            end
