   always @(posedge clk or posedge reset) begin
      if (reset) begin
         p <= 0;
         rdy <= 0;
         A <= 0;
         Q <= 0;
         M <= {8'b0, b}; // Extend b to 16 bits
         Q_1 <= 0;
         count <= 8; // Number of bits
         q_bit <= 0;
      end else if (count > 0) begin
         q_bit = Q[0:1]; // Get the least significant bit and the previous bit
         if (q_bit == 2'b01) begin
            A = A + {8'b0, a}; // Add a to A
         end else if (q_bit == 2'b10) begin
            A = A - {8'b0, a}; // Subtract a from A
         end
         // Arithmetic right shift
         {A, Q, Q_1} = {A, Q, Q_1} >> 1;
         count = count - 1;
      end else begin
         p <= {A, Q}; // Combine A and Q to get the product
         rdy <= 1; // Indicate that the result is ready
      end
   end
endmodule

