   reg [15:0] M, P;
   reg [3:0] count;
   reg Q_1;

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         P <= 16'b0;
         A <= 8'b0;
         Q <= b;
         M <= {8'b0, a};
         Q_1 <= 1'b0;
         count <= 4'b1000; // 8 iterations for 8-bit multiplication
         rdy <= 1'b0;
      end else if (count > 0) begin
         case ({Q[0], Q_1})
            2'b01: begin
               P <= P + M; // P = P + M
               A <= A + 1; // A = A + 1
            end
            2'b10: begin
               P <= P - M; // P = P - M
               A <= A - 1; // A = A - 1
            end
         endcase
         P <= P >> 1; // Arithmetic right shift
         Q_1 <= Q[0]; // Update Q_1
         Q <= {A[0], Q[7:1]}; // Shift Q
         A <= {1'b0, A[7:1]}; // Shift A
         count <= count - 1;
      end else begin
         rdy <= 1'b1; // Indicate that the multiplication is ready
         p <= P; // Output the result
      end
   end
endmodule

`timescale 1ns / 1ps
module multi_booth_8bit (p, rdy, clk, reset, a, b);
   input clk, reset;
   input [7:0] a, b;
   output reg [15:0] p;
   output reg rdy;

   reg [7:0] multiplicand, multiplier;
   reg [15:0] product;
   reg [3:0] count;
   reg [1:0] state;

   parameter IDLE = 2'b00, LOAD = 2'b01, CALCULATE = 2'b10, DONE = 2'b11;

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         p <= 16'b0;
         rdy <= 1'b0;
         state <= IDLE;
         count <= 4'b0;
      end else begin
         case (state)
            IDLE: begin
               multiplicand <= a;
               multiplier <= b;
               product <= 16'b0;
               count <= 4'b8;
               state <= LOAD;
            end

            LOAD: begin
               if (count > 0) begin
                  case (multiplier[1:0])
                     2'b01: product <= product + {8'b0, multiplicand}; // Add
                     2'b10: product <= product - {8'b0, multiplicand}; // Subtract
                     default: ; // Do nothing for 00 and 11
                  endcase
                  product <= {product[15:1], 1'b0}; // Shift right
                  multiplier <= {1'b0, multiplier[7:1]}; // Shift multiplier
                  count <= count - 1;
               end else begin
                  state <= DONE;
               end
            end

            DONE: begin
               p <= product;
               rdy <= 1'b1;
               state <= IDLE; // Go back to IDLE after done
            end
         endcase
      end
   end
endmodule

`timescale 1ns / 1ps
module multi_booth_8bit (p, rdy, clk, reset, a, b);
   input clk, reset;
   input [7:0] a, b;
   output reg [15:0] p;
   output reg rdy;

   reg [7:0] a_reg, b_reg;
   reg [15:0] product;
   reg [3:0] count;
   reg [1:0] q;
   reg [1:0] q_next;

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         p <= 0;
         rdy <= 0;
         product <= 0;
         count <= 0;
         a_reg <= 0;
         b_reg <= 0;
         q <= 0;
      end else begin
         if (count == 0) begin
            a_reg <= a;
            b_reg <= b;
            product <= 0;
            count <= 8; 
            q <= 0; 
            rdy <= 0;
         end else begin
            case (q)
               2'b00: begin
                  product = product + (a_reg << (count - 1));
                  q_next = 2'b01;
               end
               2'b01: begin
                  product = product + (a_reg << (count - 1));
                  q_next = 2'b10;
               end
               2'b10: begin
                  product = product - (a_reg << (count - 1));
                  q_next = 2'b11;
               end
               2'b11: begin
                  product = product - (a_reg << (count - 1));
                  q_next = 2'b00;
               end
            endcase
            q <= q_next;
            count <= count - 1;
         end

         if (count == 1) begin
            p <= product;
            rdy <= 1;
         end
      end
   end
endmodule

