)(
          clk,      
          rst_n,       
          mul_a,       
          mul_b, 
          mul_en_in,

          mul_en_out,      
          mul_out    
);
   input clk;           
   input rst_n; 
   input mul_en_in;      
   input [size-1:0] mul_a;       
   input [size-1:0] mul_b;       

   output reg mul_en_out;  
   output reg [size*2-1:0] mul_out;    

   reg [size*2-1:0] mul_a_reg;
   reg [size*2-1:0] mul_b_reg;

   always @(posedge clk or negedge rst_n) begin
       if (!rst_n) begin
           mul_en_out <= 1'b0;
           mul_out <= 0;
           mul_a_reg <= 0;
           mul_b_reg <= 0;
       end else begin
           if (mul_en_in) begin
               mul_a_reg <= mul_a;
               mul_b_reg <= mul_b;
               mul_en_out <= 1'b1;
           end

           if (mul_en_out) begin
               mul_out <= mul_a_reg * mul_b_reg;
           end
       end
   end
endmodule

