module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

reg [3:0] shift_reg;
reg [1:0] bit_count;
reg valid;
assign valid_out = valid;
assign dout = shift_reg[3];

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        shift_reg <= 4'b0000;
        bit_count <= 2'b00;
        valid <= 1'b0;
    end else begin
        if (bit_count == 2'b00) begin
            shift_reg <= d;
            valid <= 1'b1;
            bit_count <= bit_count + 1;
        end else if (bit_count < 2'b11) begin
            shift_reg <= {1'b0, shift_reg[3:1]};
            bit_count <= bit_count + 1;
        end else begin
            valid <= 1'b0;
            bit_count <= 2'b00;
        end
    end
end

endmodule

