module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);
    reg [3:0] shift_reg;
    reg [1:0] bit_counter;
    reg valid;
    reg serial_out;

    assign dout = serial_out;
    assign valid_out = valid;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_reg <= 4'b0;
            bit_counter <= 2'b0;
            valid <= 1'b0;
            serial_out <= 1'b0;
        end else begin
            if (bit_counter == 2'b00) begin
                shift_reg <= d;
                valid <= 1'b1;
                serial_out <= shift_reg[3];
                bit_counter <= bit_counter + 1;
            end else if (valid) begin
                serial_out <= shift_reg[3 - bit_counter];
                if (bit_counter == 2'b11) begin
                    valid <= 1'b0;
                    bit_counter <= 2'b0;
                end else begin
                    bit_counter <= bit_counter + 1;
                end
            end
        end
    end
endmodule

module parallel2serial(
    input clk,
