);

reg [1:0] bit_count;
reg [3:0] shift_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        valid_out <= 0;
        dout <= 0;
        bit_count <= 0;
        shift_reg <= 0;
    end else begin
        if (bit_count == 0) begin
            shift_reg <= d;
            valid_out <= 1;
            dout <= shift_reg[3];
            bit_count <= bit_count + 1;
        end else if (bit_count < 4) begin
            dout <= shift_reg[3 - bit_count];
            bit_count <= bit_count + 1;
        end else begin
            valid_out <= 0;
            bit_count <= 0;
        end
    end
end

endmodule

