module serial2parallel(
	input clk,
	input rst_n,
	input din_serial,
	input din_valid,
	output reg [7:0] dout_parallel,
	output reg dout_valid
);

reg [2:0] bit_count;

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		dout_parallel <= 8'b0;
		dout_valid <= 1'b0;
		bit_count <= 3'b0;
	end else if (din_valid) begin
		dout_parallel[bit_count] <= din_serial;
		bit_count <= bit_count + 1;
		if (bit_count == 3'd7) begin
			dout_valid <= 1'b1;
			bit_count <= 3'b0;
		end else begin
			dout_valid <= 1'b0;
		end
	end
end

endmodule

