module alu(
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
    );

    assign zero = (r == 32'b0);
    assign negative = r[31];
    assign carry = (aluc == ADD || aluc == ADDU) && (a[31] & b[31]) | ((a[31] | b[31]) & ~r[31]);
    assign overflow = (aluc == ADD || aluc == SUB) && ((a[31] & b[31] & ~r[31]) | (~a[31] & ~b[31] & r[31]));
    assign flag = zero | carry | negative | overflow;

    always @(*) begin
        case (aluc)
            ADD: r = a + b;
            ADDU: r = a + b;
            SUB: r = a - b;
            SUBU: r = a - b;
            AND: r = a & b;
            OR: r = a | b;
            XOR: r = a ^ b;
            NOR: r = ~(a | b);
            SLT: r = (a < b) ? 32'b1 : 32'b0;
            SLTU: r = (a < b) ? 32'b1 : 32'b0;
            SLL: r = b << a[4:0];
            SRL: r = b >> a[4:0];
            SRA: r = $signed(b) >>> a[4:0];
            SLLV: r = b << a[4:0];
            SRLV: r = b >> a[4:0];
            SRAV: r = $signed(b) >>> a[4:0];
            LUI: r = {b[15:0], 16'b0};
            default: r = 32'b0;
        endcase
    end
endmodule

