    reg [15:0] remainder;
    reg [15:0] odd_result;

    always @(*) begin
        if (B != 0) begin
            quotient = A / B;
            remainder = A % B;
        end else begin
            quotient = 16'hFFFF; // Indicate division by zero
            remainder = 16'hFFFF; // Indicate division by zero
        end
        odd_result = {15'b0, remainder[0]}; // Extract odd bit from remainder
    end

