					next_state = s3_green;
				else 
					next_state = s2_yellow;
			end
			s3_green: begin
				red = 0;
				yellow = 0;
				green = 1;
				if (counter == 8'd80) // 80 clock cycles for green
					next_state = idle;
				else 
					next_state = s3_green;
			end
			default: begin
				red = 1;
				yellow = 0;
				green = 0;
				next_state = idle;
			end
		endcase
	end

endmodule

module traffic_light
    (
        input rst_n, 
        input clk, 
        input pass_request,
        output wire[7:0] clock,
        output reg red,
        output reg yellow,
        output reg green
    );

    parameter idle = 2'd0,
              s1_red = 2'd1,
              s2_yellow = 2'd2,
              s3_green = 2'd3;

    reg [1:0] state, next_state;
    reg [7:0] counter;

    assign clock = counter;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 8'd0;
            state <= idle;
        end else begin
            counter <= counter + 1;
            state <= next_state;
        end
    end

    always @(*) begin
        case (state)
            idle: begin
                red = 1;
                yellow = 0;
                green = 0;
                if (pass_request) begin
                    next_state = s1_red;
                end else begin
                    next_state = idle;
                end
            end
            s1_red: begin
                red = 1;
                yellow = 0;
                green = 0;
                if (counter == 8'd255) begin
                    next_state = s2_yellow;
                end else begin
                    next_state = s1_red;
                end
            end
            s2_yellow: begin
                red = 0;
                yellow = 1;
                green = 0;
                if (counter == 8'd127) begin
                    next_state = s3_green;
                end else begin
                    next_state = s2_yellow;
                end
            end
            s3_green: begin
                red = 0;
                yellow = 0;
                green = 1;
                if (counter == 8'd255) begin
                    next_state = idle;
                end else begin
                    next_state = s3_green;
                end
            end
            default: begin
                next_state = idle;
                red = 0;
                yellow = 0;
                green = 0;
            end
        endcase
    end

endmodule

